if( [System.Environment]::OSVersion.Version.Build -lt 20000 ) {
	return;
}
$key = 'Registry::HKLM\SOFTWARE\Microsoft\PolicyManager\current\device\Start';
New-Item -Path $key -ItemType 'Directory' -ErrorAction 'SilentlyContinue';
Set-ItemProperty -LiteralPath $key -Name 'ConfigureStartPins' -Value $json -Type 'String';

$scripts = @(
	{
		Remove-Item -LiteralPath 'C:\Windows\System32\OneDriveSetup.exe';
	};
	{
		Remove-Item -LiteralPath 'Registry::HKLM\Software\Microsoft\WindowsUpdate\Orchestrator\UScheduler_Oobe\OutlookUpdate' -Force -ErrorAction 'SilentlyContinue';
	};
	{
        $storePath = 'Registry::HKLM\SOFTWARE\Policies\Microsoft\WindowsStore'
        if (-not (Test-Path $storePath)) {
            New-Item -Path $storePath -Force | Out-Null
        }
        Set-ItemProperty -Path $storePath -Name "DisableStoreApps" -Value 1 -Type DWord -Force
        Set-ItemProperty -Path $storePath -Name "AutoDownload" -Value 2 -Type DWord -Force
    };
	{
		$cloudContentPath = 'Registry::HKLM\SOFTWARE\Policies\Microsoft\Windows\CloudContent'
		if (-not (Test-Path $cloudContentPath)) {
    		New-Item -Path $cloudContentPath -Force | Out-Null
		}
		Set-ItemProperty -Path $cloudContentPath -Name "DisableCloudOptimizedContent" -Value 1 -Type DWord -Force
	};
	{
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Communications" /v ConfigureChatAutoInstall /t REG_DWORD /d 0 /f;
	};
	{
		Get-Content -LiteralPath 'C:\Windows\Setup\Scripts\RemovePackages.ps1' -Raw | Invoke-Expression;
	};
	{
		Get-Content -LiteralPath 'C:\Windows\Setup\Scripts\RemoveCapabilities.ps1' -Raw | Invoke-Expression;
	};
	{
		Get-Content -LiteralPath 'C:\Windows\Setup\Scripts\SetStartPins.ps1' -Raw | Invoke-Expression;
	};
	{
		netsh.exe wlan add profile filename="C:\Deploy\Wifi.xml" user=all;
	};
	{
		netsh.exe wlan connect name="YOURWIFINAME" ssid="YOURWIFISSID";
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Activity 'Execution des scripts de preparation de poste. Ne pas fermer cette fenetre.' -PercentComplete $complete;
    '*** Execution de la commmande «{0}».' -f $(
      $str = $script.ToString().Trim() -replace '\s+', ' ';
      $max = 100;
      if( $str.Length -le $max ) {
        $str;
      } else {
        $str.Substring( 0, $max - 1 ) + '…';
      }
    );
    $start = [datetime]::Now;
    & $script;
    '*** Execution de la commande en {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 >> "C:\Windows\Setup\Logs\Specialize.log";

$scripts = @(
	{
        Remove-ItemProperty -LiteralPath 'Registry::HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Run' -Name 'OneDriveSetup' -Force -ErrorAction 'Continue';
    };
    {
        reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\GameDVR" /v AppCaptureEnabled /t REG_DWORD /d 0 /f;
    };
    {
        foreach( $root in 'Registry::HKU\.DEFAULT', 'Registry::HKU\DefaultUser' ) {
          Set-ItemProperty -LiteralPath "$root\Control Panel\Keyboard" -Name 'InitialKeyboardIndicators' -Type 'String' -Value 2 -Force;
        }
    };
    {
        $cloudPath = 'Registry::HKU\DefaultUser\SOFTWARE\Policies\Microsoft\Windows\CloudContent'
        if (-not (Test-Path $cloudPath)) {
            New-Item -Path $cloudPath -Force | Out-Null
        }
        Set-ItemProperty -Path $cloudPath -Name "DisableWindowsSpotlightFeatures" -Value 1 -Type DWord -Force
        Set-ItemProperty -Path $cloudPath -Name "DisableCloudOptimizedContent" -Value 1 -Type DWord -Force
        Set-ItemProperty -Path $cloudPath -Name "DisableThirdPartySuggestions" -Value 1 -Type DWord -Force
    };
    {
        $explorerAdvanced = 'Registry::HKU\DefaultUser\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\Advanced'
        if (-not (Test-Path $explorerAdvanced)) {
            New-Item -Path $explorerAdvanced -Force | Out-Null
        }
        Set-ItemProperty -Path $explorerAdvanced -Name "ShowCopilotButton" -Value 0 -Type DWord -Force
    };
);
& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Activity 'Lancement de script pour modifier le registre utilisateur par defaut. Ne pas fermer cette fenetre.' -PercentComplete $complete;
    '*** Execution de la commande «{0}».' -f $(
      $str = $script.ToString().Trim() -replace '\s+', ' ';
      $max = 100;
      if( $str.Length -le $max ) {
        $str;
      } else {
        $str.Substring( 0, $max - 1 ) + '…';
      }
    );
    $start = [datetime]::Now;
    & $script;
    '*** Execution de la commande en {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 >> "C:\Windows\Setup\Logs\DefaultUser.log";

